/* eslint-disable max-len */

'use strict';

// MODULES //

var tape = require( 'tape' );
var proxyquire = require( 'proxyquire' );
var discreteUniform = require( '@stdlib/random/base/discrete-uniform' );
var Float64Array = require( '@stdlib/array/float64' );
var dgemm = require( '@stdlib/blas/base/dgemm' ).ndarray;
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var floor = require( '@stdlib/math/base/special/floor' );
var pow = require( '@stdlib/math/base/special/pow' );
var max = require( '@stdlib/math/base/special/max' );
var min = require( '@stdlib/math/base/special/min' );
var workspaceLength = require( './../lib/workspace_length.js' );
var winograd = require( './../lib/winograd.js' );
var depth = require( './../lib/depth.js' );
var createMatrix = require( './fixtures/create_matrix.js' );
var firstDifference = require( './fixtures/first_difference.js' );


// VARIABLES //

var SEED = 20261102;
var GUARD = 64;
var SENTINEL = -1.2345e300;
var ORDERS = [ 'row-major', 'column-major' ];

// Shapes `[ M, N, K ]` (NOTE: when `N > K`, the temporary `X` must hold the `m×n` product `P1`, i.e., `m·max(k,n)` elements):
var SHAPES = [
	[ 32, 160, 96 ],
	[ 160, 32, 96 ],
	[ 17, 9, 33 ],
	[ 31, 47, 29 ],
	[ 100, 7, 50 ],
	[ 64, 64, 64 ]
];

// Configurations `[ cutoff, levels ]`:
var CONFIGS = [
	[ 1, 100 ],
	[ 2, 3 ],
	[ 3, 100 ],
	[ 5, 2 ],
	[ 8, 1 ]
];

// Number of conventional multiplications performed by the kernel (updated by a spy):
var nleaves = 0;

var counting = proxyquire( './../lib/winograd.js', {
	'@stdlib/blas/base/dgemm': {
		'ndarray': leaf
	}
});


// FUNCTIONS //

/**
* Invokes `dgemm` and counts the invocation.
*
* @private
* @returns {Float64Array} output matrix
*/
function leaf() {
	nleaves += 1;
	return dgemm.apply( null, arguments );
}

/**
* Returns the number of times a dimension can be halved (rounding down) while remaining greater than the cutoff (i.e., the number of nonnegative integers `i` such that `floor(D/2^i) > cutoff`).
*
* @private
* @param {NonNegativeInteger} D - dimension
* @param {PositiveInteger} cutoff - recursion cutoff
* @returns {NonNegativeInteger} count
*/
function halves( D, cutoff ) {
	var i = 0;
	while ( floor( D/pow( 2, i ) ) > cutoff ) {
		i += 1;
	}
	return i;
}

/**
* Computes the recursion depth independently of the implementation (as the minimum over the dimensions of the number of admissible halving steps, capped by the number of levels).
*
* @private
* @param {NonNegativeInteger} M - number of rows
* @param {NonNegativeInteger} N - number of columns
* @param {NonNegativeInteger} K - inner dimension
* @param {PositiveInteger} cutoff - recursion cutoff
* @param {NonNegativeInteger} levels - maximum number of recursion levels
* @returns {NonNegativeInteger} depth
*/
function referenceDepth( M, N, K, cutoff, levels ) {
	return min( min( levels, halves( M, cutoff ) ), min( halves( N, cutoff ), halves( K, cutoff ) ) );
}

/**
* Computes the workspace length using the closed form `Σ_{i=1}^{L} m_i·max(k_i,n_i) + k_i·n_i`, where `m_i = floor(M/2^i)`, `n_i = floor(N/2^i)`, and `k_i = floor(K/2^i)`.
*
* @private
* @param {NonNegativeInteger} M - number of rows
* @param {NonNegativeInteger} N - number of columns
* @param {NonNegativeInteger} K - inner dimension
* @param {PositiveInteger} cutoff - recursion cutoff
* @param {NonNegativeInteger} levels - maximum number of recursion levels
* @returns {NonNegativeInteger} number of elements
*/
function referenceWorkspace( M, N, K, cutoff, levels ) {
	var total;
	var L;
	var s;
	var m;
	var n;
	var k;
	var i;

	L = referenceDepth( M, N, K, cutoff, levels );
	total = 0;
	for ( i = 1; i <= L; i++ ) {
		s = pow( 2, i );
		m = floor( M/s );
		n = floor( N/s );
		k = floor( K/s );
		total += ( m*max( k, n ) ) + ( k*n );
	}
	return total;
}

/**
* Inspects a workspace surrounded by guard elements.
*
* @private
* @param {Float64Array} W - workspace (including `GUARD` leading and trailing guard elements)
* @param {NonNegativeInteger} len - workspace length (excluding guard elements)
* @returns {NonNegativeIntegerArray} number of modified guard elements and number of workspace elements which still hold their initial value (`NaN`)
*/
function inspect( W, len ) {
	var unused;
	var guards;
	var i;

	guards = 0;
	unused = 0;
	for ( i = 0; i < W.length; i++ ) {
		if ( i < GUARD || i >= GUARD+len ) {
			if ( W[ i ] !== SENTINEL ) {
				guards += 1;
			}
		} else if ( isnan( W[ i ] ) ) {
			unused += 1;
		}
	}
	return [ guards, unused ];
}

/**
* Returns a strided matrix of random integers in `[-6,6]` (elements which do not belong to the matrix equal `NaN`).
*
* @private
* @param {Function} randi - PRNG for integers
* @param {NonNegativeInteger} rows - number of rows
* @param {NonNegativeInteger} cols - number of columns
* @param {string} order - storage layout
* @param {boolean} nan - boolean indicating whether to fill the matrix elements with `NaN`
* @returns {Object} matrix description
*/
function randomMatrix( randi, rows, cols, order, nan ) {
	var opts = {
		'order': order,
		'pad': randi( 0, 2 ),
		'offset': randi( 0, 3 ),
		'tail': 1,
		'flip1': false,
		'flip2': false
	};
	return createMatrix( rows, cols, opts, value );

	function value( i ) {
		if ( i < 0 || nan ) {
			return NaN;
		}
		return randi( -6, 6 );
	}
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof winograd, 'function', 'main export is a function' );
	t.strictEqual( typeof workspaceLength, 'function', 'main export is a function' );
	t.strictEqual( typeof depth, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns the number of recursion levels', function test( t ) {
	var mismatches;
	var values;
	var randi;
	var args;
	var i;

	values = [
		[ [ 1024, 1024, 1024, 64, 4 ], 4 ],
		[ [ 4096, 4096, 4096, 64, 100 ], 6 ],
		[ [ 100, 100, 100, 64, 4 ], 1 ],
		[ [ 64, 64, 64, 64, 4 ], 0 ],
		[ [ 65, 65, 65, 64, 4 ], 1 ],
		[ [ 129, 129, 129, 64, 4 ], 1 ],
		[ [ 130, 130, 130, 64, 4 ], 2 ],
		[ [ 37, 37, 37, 3, 100 ], 4 ],
		[ [ 257, 129, 65, 1, 100 ], 6 ],
		[ [ 300, 3, 300, 2, 100 ], 1 ],
		[ [ 300, 3, 300, 3, 100 ], 0 ],
		[ [ 0, 100, 100, 1, 100 ], 0 ],
		[ [ 100, 100, 100, 1, 0 ], 0 ],
		[ [ 2, 2, 2, 1, 100 ], 1 ]
	];
	for ( i = 0; i < values.length; i++ ) {
		args = values[ i ][ 0 ];
		t.strictEqual( depth( args[ 0 ], args[ 1 ], args[ 2 ], args[ 3 ], args[ 4 ] ), values[ i ][ 1 ], 'returns expected value for (' + args.join( ', ' ) + ')' );
	}
	randi = discreteUniform.factory({
		'seed': SEED
	});
	mismatches = 0;
	for ( i = 0; i < 5000; i++ ) {
		args = [ randi( 0, 5000 ), randi( 0, 5000 ), randi( 0, 5000 ), randi( 1, 200 ), randi( 0, 12 ) ];
		if ( depth( args[ 0 ], args[ 1 ], args[ 2 ], args[ 3 ], args[ 4 ] ) !== referenceDepth( args[ 0 ], args[ 1 ], args[ 2 ], args[ 3 ], args[ 4 ] ) ) {
			mismatches += 1;
		}
	}
	t.strictEqual( mismatches, 0, 'returns expected values for 5000 random arguments' );
	t.end();
});

tape( 'the number of recursion levels equals the number of levels performed by the kernel (7^L conventional multiplications for orders which are powers of two)', function test( t ) {
	var configs;
	var ref;
	var out;
	var A;
	var B;
	var L;
	var n;
	var i;
	var j;

	configs = [ [ 1, 100 ], [ 2, 2 ], [ 4, 100 ], [ 8, 3 ], [ 16, 100 ] ];
	for ( n = 4; n <= 64; n *= 2 ) {
		A = new Float64Array( n*n );
		B = new Float64Array( n*n );
		for ( i = 0; i < n*n; i++ ) {
			A[ i ] = ( i%7 ) - 3;
			B[ i ] = ( i%5 ) - 2;
		}
		ref = new Float64Array( n*n );
		dgemm( 'no-transpose', 'no-transpose', n, n, n, 1.0, A, n, 1, 0, B, 1, n, 0, 0.0, ref, n, 1, 0 );
		for ( j = 0; j < configs.length; j++ ) {
			L = depth( n, n, n, configs[ j ][ 0 ], configs[ j ][ 1 ] );
			out = new Float64Array( n*n );
			nleaves = 0;
			counting( n, n, n, 1.0, A, n, 1, 0, B, 1, n, 0, out, n, 1, 0, new Float64Array( workspaceLength( n, n, n, configs[ j ][ 0 ], configs[ j ][ 1 ] ) ), 0, configs[ j ][ 0 ], configs[ j ][ 1 ] );
			t.strictEqual( nleaves, pow( 7, L ), 'performs 7^' + L + ' conventional multiplications (n=' + n + ', cutoff=' + configs[ j ][ 0 ] + ', levels=' + configs[ j ][ 1 ] + ')' );
			t.strictEqual( firstDifference( ref, out, true ), -1, 'returns expected value' );
		}
	}
	t.end();
});

tape( 'the workspace length equals the closed form Σ m_i·max(k_i,n_i) + k_i·n_i (independently recomputed)', function test( t ) {
	var mismatches;
	var randi;
	var args;
	var i;
	var j;
	var k;

	for ( i = 0; i < SHAPES.length; i++ ) {
		for ( j = 0; j < CONFIGS.length; j++ ) {
			args = [ SHAPES[ i ][ 0 ], SHAPES[ i ][ 1 ], SHAPES[ i ][ 2 ], CONFIGS[ j ][ 0 ], CONFIGS[ j ][ 1 ] ];
			t.strictEqual( workspaceLength( args[ 0 ], args[ 1 ], args[ 2 ], args[ 3 ], args[ 4 ] ), referenceWorkspace( args[ 0 ], args[ 1 ], args[ 2 ], args[ 3 ], args[ 4 ] ), 'returns expected value for (' + args.join( ', ' ) + ')' );
		}
	}
	// Explicit values (when `N > K`, `X` holds `m·n` elements):
	t.strictEqual( workspaceLength( 32, 160, 96, 16, 1 ), ( 16*80 )+( 48*80 ), 'returns expected value' );
	t.strictEqual( workspaceLength( 160, 32, 96, 16, 1 ), ( 80*48 )+( 48*16 ), 'returns expected value' );
	t.strictEqual( workspaceLength( 128, 128, 128, 32, 4 ), 10240, 'returns expected value' );
	t.strictEqual( workspaceLength( 64, 64, 64, 64, 4 ), 0, 'returns expected value' );
	t.strictEqual( workspaceLength( 100, 100, 100, 1, 0 ), 0, 'returns expected value' );

	randi = discreteUniform.factory({
		'seed': SEED+1
	});
	mismatches = 0;
	for ( k = 0; k < 5000; k++ ) {
		args = [ randi( 0, 3000 ), randi( 0, 3000 ), randi( 0, 3000 ), randi( 1, 100 ), randi( 0, 12 ) ];
		if ( workspaceLength( args[ 0 ], args[ 1 ], args[ 2 ], args[ 3 ], args[ 4 ] ) !== referenceWorkspace( args[ 0 ], args[ 1 ], args[ 2 ], args[ 3 ], args[ 4 ] ) ) {
			mismatches += 1;
		}
	}
	t.strictEqual( mismatches, 0, 'returns expected values for 5000 random arguments' );
	t.end();
});

tape( 'the workspace length equals (2/3)(1-4^-L)n² for square matrices whose order is a power of two', function test( t ) {
	var mismatches;
	var count;
	var n;
	var p;
	var L;

	mismatches = 0;
	count = 0;
	for ( p = 1; p <= 12; p++ ) {
		n = pow( 2, p );
		for ( L = 1; L <= p; L++ ) {
			count += 1;
			if ( depth( n, n, n, 1, L ) !== L || workspaceLength( n, n, n, 1, L ) !== ( 2*( ( n*n )-( ( n*n )/pow( 4, L ) ) ) )/3 ) {
				mismatches += 1;
				t.fail( 'unexpected workspace length for n=' + n + ', L=' + L + ': ' + workspaceLength( n, n, n, 1, L ) );
			}
		}
	}
	t.strictEqual( mismatches, 0, 'returns expected values (' + count + ' combinations of n = 2, 4, ..., 4096 and L = 1, ..., log2(n))' );
	t.end();
});

tape( 'the kernel never accesses workspace elements outside of the computed length, uses every workspace element, never reads workspace elements before writing them, and computes correct results', function test( t ) {
	var unused;
	var guards;
	var randi;
	var alpha;
	var wrong;
	var total;
	var res;
	var len;
	var ref;
	var out;
	var cfg;
	var idx;
	var A;
	var B;
	var C;
	var W;
	var s;
	var i;
	var j;
	var k;

	randi = discreteUniform.factory({
		'seed': SEED+2
	});
	guards = 0;
	unused = 0;
	wrong = 0;
	total = 0;
	for ( i = 0; i < SHAPES.length; i++ ) {
		s = SHAPES[ i ];
		for ( j = 0; j < CONFIGS.length; j++ ) {
			cfg = CONFIGS[ j ];
			len = workspaceLength( s[ 0 ], s[ 1 ], s[ 2 ], cfg[ 0 ], cfg[ 1 ] );
			for ( k = 0; k < 8; k++ ) {
				total += 1;
				alpha = ( k%2 === 0 ) ? 1.0 : -2.0;
				A = randomMatrix( randi, s[ 0 ], s[ 2 ], ORDERS[ k%2 ], false );
				B = randomMatrix( randi, s[ 2 ], s[ 1 ], ORDERS[ floor( k/2 )%2 ], false );
				C = randomMatrix( randi, s[ 0 ], s[ 1 ], ORDERS[ floor( k/4 )%2 ], true );

				// Leading and trailing guard elements hold a sentinel, and the workspace initially holds `NaN` (any read before a write would propagate to the result):
				W = new Float64Array( GUARD+len+GUARD );
				for ( idx = 0; idx < W.length; idx++ ) {
					W[ idx ] = ( idx < GUARD || idx >= GUARD+len ) ? SENTINEL : NaN;
				}
				ref = new Float64Array( C.buf );
				out = new Float64Array( C.buf );
				dgemm( 'no-transpose', 'no-transpose', s[ 0 ], s[ 1 ], s[ 2 ], alpha, A.buf, A.s1, A.s2, A.o, B.buf, B.s1, B.s2, B.o, 0.0, ref, C.s1, C.s2, C.o );
				winograd( s[ 0 ], s[ 1 ], s[ 2 ], alpha, A.buf, A.s1, A.s2, A.o, B.buf, B.s1, B.s2, B.o, out, C.s1, C.s2, C.o, W, GUARD, cfg[ 0 ], cfg[ 1 ] );
				res = inspect( W, len );
				guards += res[ 0 ];
				unused += res[ 1 ];
				if ( firstDifference( ref, out, true ) >= 0 ) {
					wrong += 1;
					t.fail( 'returns unexpected value for (' + s.join( ', ' ) + '), cutoff=' + cfg[ 0 ] + ', levels=' + cfg[ 1 ] + ', layouts=' + k );
				}
			}
		}
	}
	t.strictEqual( guards, 0, 'guard elements are untouched (' + total + ' runs)' );
	t.strictEqual( unused, 0, 'every workspace element is written (the computed length is tight)' );
	t.strictEqual( wrong, 0, 'returns expected values' );
	t.end();
});
